import React, { useEffect, useReducer, useRef, useState } from 'react';
import './App.css';

type Basemap = {
  id: string;
  label: string;
};

// The last option is a user-named preset. Its name contains angle brackets on purpose.
const BASEMAPS: Basemap[] = [
  { id: 'satellite', label: 'Satellite' },
  { id: 'terrain', label: 'Terrain' },
  { id: 'streets', label: 'Streets' },
  { id: 'preset', label: 'My preset <draft>' }
];

type PickerState = {
  open: boolean;
  activeIndex: number;
  selectedIndex: number;
  count: number;
};

type PickerAction =
  | { type: 'toggle' }
  | { type: 'close' }
  | { type: 'choose'; index: number }
  | { type: 'key'; key: string };

type PickerOptions = {
  items: Basemap[];
  selectedId: string;
  idPrefix: string;
  label: string;
  onChange: (item: Basemap) => void;
};

function createPickerState(count: number, selectedIndex: number): PickerState {
  return { open: false, activeIndex: selectedIndex, selectedIndex, count };
}

function indexOfId(items: Basemap[], id: string): number {
  return Math.max(0, items.findIndex((item) => item.id === id));
}

// TODO 1: shared logic. Both versions must call this pure function: no DOM, no React, no callbacks.
// - 'toggle' opens the list on the selected option, or closes it
// - 'close' closes the list
// - 'choose' selects an index and closes the list
// - 'key' while closed: ArrowDown and ArrowUp open the list on the selected option
// - 'key' while open: ArrowDown and ArrowUp move the active option and stop at the ends,
//   Home and End jump to the first and last option, Enter selects the active option and closes,
//   Escape closes without selecting
// Return the same object when an action changes nothing.
function pickerReducer(state: PickerState, action: PickerAction): PickerState {
  return state;
}

// TODO 2: the plain JavaScript version.
// - Build the DOM described in the task inside `host`, once, in the constructor.
// - Keep the state in one object from createPickerState and update the DOM from it in one render method.
// - Use one click listener on the list for every option (event delegation).
// - Close the list on a click outside the picker by listening on `document`.
// - Call options.onChange(item) only when the selection really changes.
class BasemapPicker {
  constructor(host: HTMLElement, options: PickerOptions) {
    host.textContent = 'Plain JavaScript picker not implemented yet.';
  }

  destroy(): void {
    // TODO: remove every listener you added, including the one on document, and remove the picker.
  }
}

// TODO 3: the React version. Same props, same DOM contract and the same pickerReducer.
// Do not mount BasemapPicker inside it: move the state, the markup and the listeners into React.
function ReactBasemapPicker(props: PickerOptions) {
  return <p className="todo">React picker not implemented yet.</p>;
}

// Given: mounts the class version into a host element and destroys it on unmount.
function VanillaBasemapPicker(props: PickerOptions) {
  const hostRef = useRef<HTMLDivElement>(null);
  const onChangeRef = useRef(props.onChange);
  onChangeRef.current = props.onChange;

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const picker = new BasemapPicker(host, { ...props, onChange: (item) => onChangeRef.current(item) });
    return () => picker.destroy();
    // The class owns its DOM after mount, so this wrapper mounts it once.
  }, []);

  return <div className="picker-host" ref={hostRef} />;
}

type ChangeLog = {
  label: string;
  changes: number;
};

function useChangeLog(initial: Basemap) {
  const [log, setLog] = useState<ChangeLog>({ label: initial.label, changes: 0 });
  const record = (item: Basemap) => setLog((current) => ({ label: item.label, changes: current.changes + 1 }));
  return [log, record] as const;
}

function Status({ log }: { log: ChangeLog }) {
  return (
    <p className="status" aria-live="polite">
      Selected <strong className="status-value">{log.label}</strong>, changes reported:{' '}
      <span className="status-count">{log.changes}</span>
    </p>
  );
}

export default function App() {
  const [vanillaLog, recordVanilla] = useChangeLog(BASEMAPS[0]);
  const [reactLog, recordReact] = useChangeLog(BASEMAPS[0]);

  return (
    <main className="main">
      <header className="header">
        <h1 className="title">Basemap Picker</h1>
        <p className="subtitle">Write one picker twice, as a plain JavaScript class and as a React component. Both must pass the same checks.</p>
      </header>
      <div className="panels">
        <section className="panel" data-version="vanilla" aria-labelledby="vanilla-title">
          <h2 className="panel-title" id="vanilla-title">
            Plain JavaScript
          </h2>
          <VanillaBasemapPicker items={BASEMAPS} selectedId="satellite" idPrefix="vanilla-basemap" label="Basemap" onChange={recordVanilla} />
          <Status log={vanillaLog} />
        </section>
        <section className="panel" data-version="react" aria-labelledby="react-title">
          <h2 className="panel-title" id="react-title">
            React
          </h2>
          <ReactBasemapPicker items={BASEMAPS} selectedId="satellite" idPrefix="react-basemap" label="Basemap" onChange={recordReact} />
          <Status log={reactLog} />
        </section>
      </div>
    </main>
  );
}

