:root {
  color-scheme: dark;
}

html, body {
  margin: 0;
  min-height: 100%;
  background: #020617;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

.main {
  min-height: 100vh;
  box-sizing: border-box;
  background: #020617;
  color: #e5e7eb;
  display: grid;
  align-content: start;
  justify-items: center;
  gap: 20px;
  padding: 24px 16px;
}

.header {
  width: 100%;
  max-width: 760px;
  display: grid;
  gap: 4px;
}

.title {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
}

.subtitle {
  margin: 0;
  font-size: 13px;
  line-height: 1.5;
  color: #9ca3af;
}

.panels {
  width: 100%;
  max-width: 760px;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 16px;
}

.panel {
  border: 1px solid #1f2937;
  border-radius: 16px;
  padding: 16px;
  display: grid;
  align-content: start;
  gap: 12px;
}

.panel-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
}

.picker {
  position: relative;
  display: grid;
  gap: 6px;
}

.picker-label {
  font-size: 13px;
  color: #9ca3af;
}

.picker-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  border-radius: 10px;
  border: 1px solid #374151;
  background: #0b1220;
  color: #e5e7eb;
  padding: 9px 12px;
  font: inherit;
  font-size: 14px;
  text-align: left;
  cursor: pointer;
}

.picker-trigger::after {
  content: '';
  flex: none;
  width: 8px;
  height: 8px;
  border-right: 2px solid #9ca3af;
  border-bottom: 2px solid #9ca3af;
  transform: translateY(-2px) rotate(45deg);
}

.picker-trigger[aria-expanded='true']::after {
  transform: translateY(2px) rotate(225deg);
}

.picker-trigger:focus-visible {
  outline: 2px solid #a3e635;
  outline-offset: 2px;
}

.picker-list {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  z-index: 10;
  margin: 6px 0 0;
  padding: 4px;
  list-style: none;
  border-radius: 10px;
  border: 1px solid #374151;
  background: #0b1220;
  box-shadow: 0 12px 24px rgba(0, 0, 0, 0.45);
}

.picker-list[hidden] {
  display: none;
}

.picker-option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-radius: 8px;
  padding: 8px 10px;
  font-size: 14px;
  overflow-wrap: anywhere;
  cursor: pointer;
}

.picker-option:hover,
.picker-option.is-active {
  background: #1f2937;
}

.picker-option.is-active {
  box-shadow: inset 0 0 0 1px #a3e635;
}

.picker-option[aria-selected='true'] {
  color: #a3e635;
  font-weight: 600;
}

.picker-option[aria-selected='true']::after {
  content: '✓';
  flex: none;
}

.status {
  margin: 0;
  font-size: 13px;
  line-height: 1.5;
  color: #9ca3af;
}

.status-value,
.status-count {
  color: #e5e7eb;
}

.todo {
  margin: 0;
  font-size: 13px;
  color: #f97316;
}
